#include <bits/stdc++.h>

using namespace std;

int dfs(int v, int p, int to, const vector<vector<int>> &g, vector<int> &max_depth) {
    int ans = 0;
    bool has_to = false;
    for (int i : g[v]) {
        if (i == p) {
            continue;
        }
        int tmp = dfs(i, v, to, g, max_depth);
        if (tmp == -1) {
            has_to = true;
        } else {
            ans = max(ans, tmp + 1);
        }
    }
    if (has_to || v == to) {
        max_depth.emplace_back(ans);
        return -1;
    } else {
        return ans;
    }
}

int solve(const vector<vector<int>> &g, int to) {
    vector<int> max_depth;
    dfs(0, -1, to, g, max_depth);
    int n = max_depth.size();
    reverse(max_depth.begin(), max_depth.end());
    int first = 0, second = n - 1;
    while (true) {
        {
            int value1 = max_depth[first] + first;
            bool valid = true;
            for (int j = second; j > first; --j) {
                if (value1 <= max_depth[j] + (n - j - 1)) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                return 0;
            }
            ++first;
            if (first == second) {
                return 1;
            }
        }
        {
            int value2 = max_depth[second] + (n - second - 1);
            bool valid = true;
            for (int j = first; j < second; ++j) {
                if (value2 < max_depth[j] + j) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                return 1;
            }
            --second;
            if (first == second) {
                return 0;
            }
        }
    }
}

void solve() {
    int n;
    cin >> n;
    vector<vector<int>> g(n);
    for (int i = 0; i < n - 1; ++i) {
        int a, b;
        cin >> a >> b;
        g[a - 1].push_back(b - 1);
        g[b - 1].push_back(a - 1);
    }
    int s, f;
    cin >> s >> f;
    --s, --f;
    int ans = solve(g, s);
    if (ans == 0) {
        cout << "Alice\n";
    } else {
        cout << "Bob\n";
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int t;
    cin >> t;
    while (t--)
        solve();
}

#include <bits/stdc++.h>

using namespace std;
const int maxn = 2e5 + 12;

vector<int> g[maxn], del[maxn], add[maxn];
vector<int> ord;
int ans[maxn];
int dp[maxn];
int n, m, k;

bool calc(int v, int p, int f){
    bool is = 0;
    if(v == f) is = 1;
    dp[v] = 1;
    for(int to:g[v]){
        if(to == p){
            continue;
        }
        bool fg = calc(to, v, f);
        is |= fg;
        if(fg == 0){
            dp[v] = max(dp[v], dp[to] + 1);
        }
    }
    if(is){
        ord.push_back(v);
    }
    return is;
}

struct sparse {
    int mx[20][200200], lg[200200];
    int n;
    void build(vector<int> &a){
        n = a.size();
        for(int i=0;i<n;i++){
            mx[0][i] = a[i];
        }
        lg[0] = lg[1] = 0;
        for(int i=2;i<=n;i++){
            lg[i] = lg[i/2] + 1;
        }
        for(int k=1;k<20;k++){
            for(int i=0;i + (1 << k) - 1 < n;i++){
                mx[k][i] = max(mx[k-1][i], mx[k-1][i + (1 << (k - 1))]);
            }
        }
    }
    int get (int l, int r) {
        if(l > r) return -1e9;
        int k = lg[r-l+1];
        return max(mx[k][l], mx[k][r - (1 << k) + 1]);
    }
} st_a, st_b;

void solve(int v){
    ord.clear();
    calc(1, 0, v);
    reverse(ord.begin(), ord.end());
    m = ord.size();
    vector<int> a(m+1), b(m+1);
    vector<int> fa(m+1, 1e9), fb(m+1, -1e9);
    for(int i=0;i<m;i++){
        a[i] = dp[ord[i]] + i;
        b[i] = dp[ord[i]] - i;
        del[i].clear();
        add[i].clear();
    }
    st_a.build(a);
    st_b.build(b);
    multiset<int> s;
    for(int i=1;i<m;i++){
        int pos = i;
        for(int l=i+1, r=m-1;l<=r;){
            int mid = l + r >> 1;
            if(st_b.get(i+1 , mid) + mid < a[i] - i){
                pos = mid;
                l = mid + 1;
            }
            else r = mid - 1;
        }
        if(i < pos){
            add[min(m, 2 * i)].push_back(i);
            del[min(m, pos + i)].push_back(i);
        }
        for(int x:add[i]){
            s.insert(x);
        }
        if(s.size()) fa[i] = *s.begin();
        for(int x:del[i]){
            s.erase(s.find(x));
        }
    }
    s.clear();
    for(int i=0;i<=m;i++){
        add[i].clear();
        del[i].clear();
    }
    for(int i=1;i<m;i++){
        int pos = i;
        for(int l=1, r = i-1;l<=r;){
            int mid = l + r >> 1;
            if(st_a.get(mid, i-1) - mid + 1 <= b[i] + i){
                pos = mid;
                r = mid - 1;
            }
            else l = mid + 1;
        }
        pos--;
        if(pos >= 0){
            add[min(m, pos + i)].push_back(i);
            del[min(m, 2 * i - 1)].push_back(i);
        }
        for(int x:add[i]){
            s.insert(x);
        }
        if(s.size()) fb[i] = *s.rbegin();
        for(int x:del[i]){
            s.erase(s.find(x));
        }
    }
    for(int i=m-1;i>0;i--){
        b[i] = max(b[i+1] + 1, dp[ord[i]]);
        if(b[i] >= st_a.get(1, i-1)){
            fb[i] = i;
        }
        if(a[0] > max(st_b.get(1, i-1) + i, b[i])){
            fa[i] = 0;
        }
        ans[ord[i]] = 0;
        if(fa[i] <= i - fb[i]){
            ans[ord[i]] = 1;
        }
    }
}

void solve(){
    cin >> n;
    for(int i=1;i<=n;i++){
        g[i].clear();
    }
    for(int i=1;i<n;i++){
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    int u, v;
    cin >> u >> v;
    solve(u), solve(v);
    ord.clear();
    calc(v, 0, u);
    auto p = ord;
    for(int x:p){
        if(ans[x] == 1){
            cout << "Alice\n";
        }
        else{
            cout << "Bob\n";
        }
    }
}

int main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int t = 1;
    cin >> t;
    while(t--){
        solve();
    }
}
